import openpyxl, os, sys
from openpyxl.utils import get_column_letter
out = '/root/output/result.xlsx'
print('exists', os.path.exists(out), 'size', os.path.getsize(out) if os.path.exists(out) else None)
wb = openpyxl.load_workbook(out, data_only=False)
ws = wb['Task']

expected_cells = []
expected_cells += [f'{get_column_letter(c)}{r}' for r in list(range(12,18))+list(range(19,25))+list(range(26,32)) for c in range(8,13)]
expected_cells += [f'{get_column_letter(c)}{r}' for r in range(35,41) for c in range(8,13)]
expected_cells += [f'{get_column_letter(c)}{r}' for r in list(range(42,48))+[50] for c in range(8,13)]

missing=[]
xlfn=[]
print('=== Task formulas H12:L50 ===')
for r in range(12,51):
    row_entries=[]
    for c in range(8,13):
        coord=f'{get_column_letter(c)}{r}'
        val=ws[coord].value
        if coord in expected_cells:
            if not val:
                missing.append(coord)
            if isinstance(val, str) and '_xlfn.' in val:
                xlfn.append((coord,val))
            row_entries.append(f'{coord}: {val!r}')
        elif val is not None:
            row_entries.append(f'{coord}: {val!r}')
    if row_entries:
        print('  ' + ' | '.join(row_entries))
print('missing_count', len(missing), missing)
print('xlfn_count', len(xlfn), xlfn)

# Structural checks against required formula patterns.
checks=[]
for r in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    for c in range(8,13):
        l=get_column_letter(c)
        expected=f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({l}$10,Data!$H$4:$L$4,0))'
        checks.append((f'{l}{r}', expected))
for off,r in enumerate(range(35,41)):
    for c in range(8,13):
        l=get_column_letter(c)
        expected=f'=({l}{12+off}-{l}{19+off})/{l}{26+off}*100'
        checks.append((f'{l}{r}', expected))
stat_templates={42:'=MIN({c}35:{c}40)',43:'=MAX({c}35:{c}40)',44:'=MEDIAN({c}35:{c}40)',45:'=AVERAGE({c}35:{c}40)',46:'=PERCENTILE({c}35:{c}40,0.25)',47:'=PERCENTILE({c}35:{c}40,0.75)'}
for c in range(8,13):
    l=get_column_letter(c)
    for r,t in stat_templates.items():
        checks.append((f'{l}{r}', t.format(c=l)))
    checks.append((f'{l}50', f'=SUMPRODUCT({l}35:{l}40,{l}26:{l}31)/SUM({l}26:{l}31)'))

mismatches=[]
for coord, exp in checks:
    got=ws[coord].value
    if got != exp:
        mismatches.append((coord, got, exp))
print('mismatch_count', len(mismatches))
for item in mismatches[:20]:
    print('MISMATCH', item)
if missing or xlfn or mismatches:
    sys.exit(1)
print('validation_ok')
